//! Runs every folder under tests/cases, tests/stops and tests/errors (P2R-70 to P2R-74, P2R-76).
//!
//! `PHP2RUST_BLESS=1 cargo test --test folders` rewrites every expected.rs and expected.txt
//! from the current tool output. CI never sets it.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::{Command, Output};

const HEADER: &str =
    "// Generated by php2rust. In release builds set overflow-checks = true, see the README.\n";

fn bless() -> bool {
    std::env::var_os("PHP2RUST_BLESS").is_some()
}

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn name(dir: &Path) -> String {
    dir.file_name()
        .and_then(|n| n.to_str())
        .unwrap_or_default()
        .to_owned()
}

fn text(bytes: &[u8]) -> String {
    String::from_utf8_lossy(bytes).into_owned()
}

fn folders(kind: &str) -> Vec<PathBuf> {
    let Ok(entries) = fs::read_dir(root().join("tests").join(kind)) else {
        return Vec::new();
    };
    let mut dirs: Vec<PathBuf> = entries
        .map(|entry| entry.expect("readable test folder").path())
        .filter(|path| path.is_dir())
        .collect();
    dirs.sort();
    dirs
}

fn run(program: &str, args: &[&str], dir: &Path) -> Output {
    Command::new(program)
        .args(args)
        .current_dir(dir)
        .output()
        .unwrap_or_else(|err| panic!("cannot run {program}: {err}"))
}

fn tool(args: &[&str], dir: &Path) -> Output {
    run(env!("CARGO_BIN_EXE_php2rust"), args, dir)
}

/// Fails loudly when a tool the checks need is missing or has the wrong version: a skipped
/// behaviour check looks exactly like a pass.
fn check_toolchain() {
    let rustc = text(&run("rustc", &["--version"], &root()).stdout);
    assert!(
        rustc.starts_with("rustc 1.99.0 "),
        "the tests need the pinned rustc 1.99.0, found: {rustc}"
    );
    let rustfmt = run("rustfmt", &["--version"], &root());
    assert!(
        rustfmt.status.success(),
        "rustfmt is missing: {}",
        text(&rustfmt.stderr)
    );
    let php = text(&run("php", &["-n", "-r", "echo PHP_VERSION;"], &root()).stdout);
    assert!(
        php.starts_with("8.5."),
        "the tests need PHP 8.5, found: {php}"
    );
}

#[test]
fn folders_behave_as_the_spec_says() {
    check_toolchain();
    let scratch = std::env::temp_dir().join(format!("php2rust-tests-{}", std::process::id()));
    fs::create_dir_all(&scratch).expect("scratch directory");
    let mut failures: Vec<String> = Vec::new();
    for dir in folders("cases") {
        if let Err(why) = case(&dir, &scratch) {
            failures.push(format!("cases/{}: {why}", name(&dir)));
        }
    }
    for dir in folders("stops") {
        if let Err(why) = stop(&dir) {
            failures.push(format!("stops/{}: {why}", name(&dir)));
        }
    }
    for dir in folders("errors") {
        if let Err(why) = error(&dir) {
            failures.push(format!("errors/{}: {why}", name(&dir)));
        }
    }
    let _ = fs::remove_dir_all(&scratch);
    assert!(
        failures.is_empty(),
        "{} folder(s) failed:\n\n{}",
        failures.len(),
        failures.join("\n\n")
    );
}

/// P2R-70 to P2R-72: same text, clean Rust, same printed output as PHP.
fn case(dir: &Path, scratch: &Path) -> Result<(), String> {
    let first = tool(&["input.php"], dir);
    if first.status.code() != Some(0) || !first.stderr.is_empty() {
        return Err(format!(
            "exit {:?}, stderr:\n{}",
            first.status.code(),
            text(&first.stderr)
        ));
    }
    if tool(&["input.php"], dir).stdout != first.stdout {
        return Err("two runs gave different output (P2R-06)".into());
    }
    let expected_path = dir.join("expected.rs");
    if bless() {
        fs::write(&expected_path, &first.stdout).map_err(|e| e.to_string())?;
    }
    let expected = fs::read(&expected_path).map_err(|e| format!("expected.rs: {e}"))?;
    if first.stdout != expected {
        return Err(format!(
            "output differs from expected.rs\n-- expected\n{}-- actual\n{}",
            text(&expected),
            text(&first.stdout)
        ));
    }
    let source = text(&expected);
    if !source.starts_with(HEADER) {
        return Err("expected.rs does not start with the P2R-52 line".into());
    }
    let format = run(
        "rustfmt",
        &["--edition", "2024", "--check", "expected.rs"],
        dir,
    );
    if !format.status.success() {
        return Err(format!(
            "rustfmt --check failed (P2R-51):\n{}",
            text(&format.stdout)
        ));
    }
    let program = source.lines().any(|line| line == "fn main() {");
    let binary = scratch.join(name(dir));
    let target = binary.to_str().expect("UTF-8 scratch path");
    let mut args = vec!["--edition", "2024", "-D", "warnings", "-o", target];
    if !program {
        args.extend(["--crate-type", "lib"]);
    }
    args.push("expected.rs");
    let build = run("rustc", &args, dir);
    if !build.status.success() {
        return Err(format!("rustc failed (P2R-50):\n{}", text(&build.stderr)));
    }
    if !program {
        return Ok(());
    }
    let php = run(
        "php",
        &[
            "-n",
            "-d",
            "display_errors=stderr",
            "-d",
            "error_reporting=E_ALL",
            "input.php",
        ],
        dir,
    );
    if php.status.code() != Some(0) || !php.stderr.is_empty() {
        return Err(format!(
            "PHP run failed, exit {:?}:\n{}",
            php.status.code(),
            text(&php.stderr)
        ));
    }
    let rust = run(target, &[], dir);
    if rust.status.code() != Some(0) {
        return Err(format!(
            "Rust run failed, exit {:?}:\n{}",
            rust.status.code(),
            text(&rust.stderr)
        ));
    }
    if php.stdout.is_empty() {
        return Err("the case prints nothing (P2R-72)".into());
    }
    if php.stdout != rust.stdout {
        return Err(format!(
            "stdout differs\n-- php\n{}-- rust\n{}",
            text(&php.stdout),
            text(&rust.stdout)
        ));
    }
    Ok(())
}

/// P2R-73: refused with the expected problem lines, nothing written.
fn stop(dir: &Path) -> Result<(), String> {
    for args in [&["input.php"][..], &["input.php", "-o", "out.rs"][..]] {
        let result = tool(args, dir);
        if bless() {
            fs::write(dir.join("expected.txt"), &result.stderr).map_err(|e| e.to_string())?;
        }
        let expected = fs::read_to_string(dir.join("expected.txt"))
            .map_err(|e| format!("expected.txt: {e}"))?;
        let stderr = text(&result.stderr);
        if result.status.code() != Some(1) {
            return Err(format!(
                "{args:?}: exit {:?}, expected 1\n{stderr}",
                result.status.code()
            ));
        }
        if stderr != expected {
            return Err(format!(
                "{args:?}: stderr differs\n-- expected\n{expected}-- actual\n{stderr}"
            ));
        }
        if !result.stdout.is_empty() {
            return Err(format!("{args:?}: stdout is not empty (P2R-05)"));
        }
        if dir.join("out.rs").exists() {
            let _ = fs::remove_file(dir.join("out.rs"));
            return Err(format!("{args:?}: out.rs was created (P2R-05)"));
        }
    }
    Ok(())
}

/// P2R-74: exit 2 with the expected reason, every file in the folder unchanged.
fn error(dir: &Path) -> Result<(), String> {
    let args_text =
        fs::read_to_string(dir.join("args.txt")).map_err(|e| format!("args.txt: {e}"))?;
    let args: Vec<&str> = args_text.lines().collect();
    let before = snapshot(dir)?;
    let result = tool(&args, dir);
    let after = snapshot(dir)?;
    if bless() {
        fs::write(dir.join("expected.txt"), &result.stderr).map_err(|e| e.to_string())?;
    }
    let expected =
        fs::read_to_string(dir.join("expected.txt")).map_err(|e| format!("expected.txt: {e}"))?;
    let stderr = text(&result.stderr);
    if result.status.code() != Some(2) {
        return Err(format!(
            "exit {:?}, expected 2\n{stderr}",
            result.status.code()
        ));
    }
    if stderr != expected {
        return Err(format!(
            "stderr differs\n-- expected\n{expected}-- actual\n{stderr}"
        ));
    }
    if !result.stdout.is_empty() {
        return Err("stdout is not empty (P2R-05)".into());
    }
    if before != after {
        return Err("files in the folder changed (P2R-74)".into());
    }
    Ok(())
}

/// Every file in the folder except expected.txt, by name, with its bytes.
fn snapshot(dir: &Path) -> Result<BTreeMap<String, Vec<u8>>, String> {
    let mut files = BTreeMap::new();
    for entry in fs::read_dir(dir).map_err(|e| e.to_string())? {
        let path = entry.map_err(|e| e.to_string())?.path();
        let file = name(&path);
        if file != "expected.txt" {
            files.insert(file, fs::read(&path).map_err(|e| e.to_string())?);
        }
    }
    Ok(files)
}
